#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 9am 10:00 x >/dev/null 2>&1; [ $? = 2 ] || { echo "start 9am should exit 2"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10am x >/dev/null 2>&1; [ $? = 2 ] || { echo "end 10am should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail

